-- THQ ERP v5.2 GST & Compliance — Stage A foundation.
-- Migration 214 is additive/backward-compatible with v5.1.0.
-- It does NOT connect to a GSP/IRP and does NOT change historical tax journals.
begin;

insert into public.modules(key,name,description,category,is_core,sort_order,is_active,is_beta,requires_configuration)
values('gst_compliance','GST & Compliance','India GST configuration, tax engine, e-Invoice/e-Way Bill readiness, returns and reconciliation','Compliance',false,45,true,false,true)
on conflict(key) do update set name=excluded.name,description=excluded.description,category=excluded.category,sort_order=excluded.sort_order,is_active=true,is_beta=false,requires_configuration=true;

insert into public.permissions(key,module_key,name,description) values
 ('gst_compliance.view','gst_compliance','View GST & Compliance','View GST setup, tax diagnostics and compliance status'),
 ('gst_compliance.manage','gst_compliance','Manage GST Data','Manage GST registrations, party GST identities and product tax profiles'),
 ('gst_compliance.configure','gst_compliance','Configure GST Integration','Configure GST registrations and provider-neutral compliance settings'),
 ('gst_compliance.einvoice','gst_compliance','Manage E-Invoice','Generate/retry/recover e-Invoice operations when a provider is configured'),
 ('gst_compliance.cancel_irn','gst_compliance','Cancel IRN','Request controlled IRN cancellation'),
 ('gst_compliance.ewaybill','gst_compliance','Manage E-Way Bill','Generate/update/cancel E-Way Bills when enabled'),
 ('gst_compliance.returns','gst_compliance','Manage GST Returns','Prepare and review GST return workspaces'),
 ('gst_compliance.reconcile','gst_compliance','GST Reconciliation','Perform GST/ITC reconciliation and resolve exceptions'),
 ('gst_compliance.submit','gst_compliance','Submit GST Returns','Submit GST return data through a configured provider'),
 ('gst_compliance.period_lock','gst_compliance','Lock GST Periods','Lock/unlock GST filing periods with audit controls')
on conflict(key) do update set module_key=excluded.module_key,name=excluded.name,description=excluded.description;

insert into public.role_permissions(role_id,permission_key)
select r.id,p.key from public.roles r join public.permissions p on p.module_key='gst_compliance'
where r.key='owner' on conflict do nothing;

insert into public.role_permissions(role_id,permission_key)
select r.id,x.permission_key from public.roles r join (values
 ('accountant','gst_compliance.view'),('accountant','gst_compliance.returns'),('accountant','gst_compliance.reconcile'),
 ('manager','gst_compliance.view'),('manager','gst_compliance.manage'),('manager','gst_compliance.einvoice')
) x(role_key,permission_key) on x.role_key=r.key on conflict do nothing;

insert into public.tenant_modules(tenant_id,module_key,enabled)
select distinct tm.tenant_id,'gst_compliance',true from public.tenant_modules tm
where tm.enabled and tm.module_key in('sales','purchases','accounting','reports')
on conflict(tenant_id,module_key) do nothing;

insert into public.business_template_modules(template_id,module_key)
select distinct btm.template_id,'gst_compliance' from public.business_template_modules btm where btm.module_key in('accounting','reports') on conflict do nothing;
insert into public.subscription_plan_modules(plan_id,module_key)
select distinct spm.plan_id,'gst_compliance' from public.subscription_plan_modules spm where spm.module_key in('accounting','reports') on conflict do nothing;

insert into public.app_menu_nodes_v45(tenant_id,app_key,node_key,node_type,label,icon_key,sort_order,enabled,collapsed_by_default,metadata)
select s.tenant_id,'client','compliance','group','Compliance','compliance',45,true,false,'{}'::jsonb
from (select null::uuid tenant_id union select distinct tenant_id from public.app_menu_nodes_v45 where tenant_id is not null and app_key='client') s
on conflict do nothing;
insert into public.app_menu_nodes_v45(tenant_id,app_key,node_key,node_type,module_key,parent_id,label,icon_key,sort_order,enabled,collapsed_by_default,metadata)
select p.tenant_id,'client','gst_compliance','module','gst_compliance',p.id,'GST & Compliance','compliance',10,true,false,'{}'::jsonb
from public.app_menu_nodes_v45 p where p.app_key='client' and p.node_key='compliance' and p.node_type='group' on conflict do nothing;

