create table if not exists public.gst_registrations_v520(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,gstin text not null,pan text,legal_name text not null,trade_name text,registration_type text not null default 'regular' check(registration_type in('regular','composition','casual','sez','isd','tcs','tds','non_resident','other')),state_code text not null references public.gst_state_master_v520(code),address_line1 text,address_line2 text,city text,postal_code text,country text not null default 'India',einvoice_enabled boolean not null default false,ewaybill_enabled boolean not null default false,returns_enabled boolean not null default true,provider_key text,provider_config jsonb not null default '{}'::jsonb,validation_status text not null default 'local_validated' check(validation_status in('review_required','local_validated','provider_validated','invalid')),active boolean not null default true,effective_from date not null default current_date,effective_to date,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,gstin),check(effective_to is null or effective_to>=effective_from));
create index if not exists idx_gst_registrations_v520_tenant_active on public.gst_registrations_v520(tenant_id,active,state_code);
create table if not exists public.gst_location_registrations_v520(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,location_id uuid not null references public.business_locations(id) on delete cascade,registration_id uuid not null references public.gst_registrations_v520(id) on delete cascade,effective_from date not null default current_date,effective_to date,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from));
create unique index if not exists ux_gst_location_registrations_v520_current on public.gst_location_registrations_v520(tenant_id,location_id) where effective_to is null;
create index if not exists idx_gst_location_registrations_v520_reg on public.gst_location_registrations_v520(tenant_id,registration_id);
create table if not exists public.gst_party_registrations_v520(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,party_type text not null check(party_type in('customer','supplier')),party_id uuid not null,registration_type text not null default 'unregistered' check(registration_type in('registered','unregistered','composition','sez','export','exempt')),gstin text,pan text,legal_name text,trade_name text,state_code text references public.gst_state_master_v520(code),place_of_supply_code text references public.gst_state_master_v520(code),address_line1 text,address_line2 text,city text,postal_code text,country text not null default 'India',is_default boolean not null default true,validation_status text not null default 'review_required' check(validation_status in('review_required','local_validated','provider_validated','invalid','not_applicable')),active boolean not null default true,effective_from date not null default current_date,effective_to date,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),check((registration_type in('registered','composition','sez') and gstin is not null) or registration_type in('unregistered','export','exempt')));
create index if not exists idx_gst_party_registrations_v520_party on public.gst_party_registrations_v520(tenant_id,party_type,party_id,active);
create unique index if not exists ux_gst_party_registrations_v520_default on public.gst_party_registrations_v520(tenant_id,party_type,party_id) where active and is_default and effective_to is null;
create table if not exists public.gst_product_tax_profiles_v520(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,variant_id uuid not null references public.product_variants(id) on delete cascade,supply_kind text not null check(supply_kind in('goods','service')),hsn_sac text,taxability text not null default 'taxable' check(taxability in('taxable','nil_rated','exempt','non_gst')),gst_rate numeric(7,3) not null default 0 check(gst_rate>=0 and gst_rate<=100),cess_rate numeric(7,3) not null default 0 check(cess_rate>=0 and cess_rate<=100),cess_per_unit numeric(18,4) not null default 0 check(cess_per_unit>=0),tax_inclusive boolean not null default false,reverse_charge boolean not null default false,validation_status text not null default 'review_required' check(validation_status in('review_required','locally_validated','verified')),source text not null default 'manual',notes text,active boolean not null default true,effective_from date not null default current_date,effective_to date,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),check(hsn_sac is null or hsn_sac ~ '^[0-9]{4}([0-9]{2})?([0-9]{2})?$'));
create index if not exists idx_gst_product_tax_profiles_v520_variant on public.gst_product_tax_profiles_v520(tenant_id,variant_id,active,effective_from desc);
create unique index if not exists ux_gst_product_tax_profiles_v520_current on public.gst_product_tax_profiles_v520(tenant_id,variant_id) where active and effective_to is null;
alter table public.gst_registrations_v520 enable row level security;alter table public.gst_location_registrations_v520 enable row level security;alter table public.gst_party_registrations_v520 enable row level security;alter table public.gst_product_tax_profiles_v520 enable row level security;
revoke all on public.gst_registrations_v520,public.gst_location_registrations_v520,public.gst_party_registrations_v520,public.gst_product_tax_profiles_v520 from anon,authenticated;

create or replace function private.gst_v520_has_access(p_tenant_id uuid,p_permission text default 'gst_compliance.view') returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select private.erp_user_has_tenant_access(p_tenant_id) and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,p_permission)); $$;
revoke all on function private.gst_v520_has_access(uuid,text) from public,anon,authenticated;
create or replace function public.gst_state_code_resolve_v520(p_value text) returns text language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v text:=trim(coalesce(p_value,''));v_code text;begin if v='' then return null;end if;if v ~ '^[0-9]{2}$' and exists(select 1 from public.gst_state_master_v520 where code=v) then return v;end if;select s.code into v_code from public.gst_state_master_v520 s where lower(s.name)=lower(v) or exists(select 1 from jsonb_array_elements_text(s.aliases) a(value) where lower(a.value)=lower(v)) order by s.active desc,s.code limit 1;return v_code;end $$;
revoke all on function public.gst_state_code_resolve_v520(text) from public,anon;grant execute on function public.gst_state_code_resolve_v520(text) to authenticated;
create or replace function public.gst_gstin_validate_v520(p_gstin text) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v text:=upper(regexp_replace(coalesce(p_gstin,''),'\s','','g'));chars constant text:='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';i integer;val integer;factor integer;prod integer;sm integer:=0;check_index integer;expected text;actual text;fmt boolean;state_ok boolean;checksum_ok boolean;state_code text;pan text;begin fmt:=v ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$';state_code:=case when length(v)>=2 then substring(v,1,2) end;pan:=case when length(v)>=12 then substring(v,3,10) end;state_ok:=state_code is not null and exists(select 1 from public.gst_state_master_v520 s where s.code=state_code and not s.is_special_code);checksum_ok:=false;expected:=null;actual:=case when length(v)=15 then substring(v,15,1) end;if fmt then for i in 1..14 loop val:=position(substring(v,i,1) in chars)-1;factor:=case when mod(i,2)=1 then 1 else 2 end;prod:=val*factor;sm:=sm+(prod/36)+mod(prod,36);end loop;check_index:=mod(36-mod(sm,36),36);expected:=substring(chars,check_index+1,1);checksum_ok:=expected=actual;end if;return jsonb_build_object('input',p_gstin,'normalized',v,'format_valid',fmt,'state_code',state_code,'state_valid',state_ok,'pan',pan,'expected_check_digit',expected,'actual_check_digit',actual,'checksum_valid',checksum_ok,'structurally_valid',fmt and state_ok and checksum_ok,'network_status','not_checked');end $$;
revoke all on function public.gst_gstin_validate_v520(text) from public,anon;grant execute on function public.gst_gstin_validate_v520(text) to authenticated;
create or replace function private.gst_profile_for_variant_v520(p_tenant_id uuid,p_variant_id uuid,p_date date) returns public.gst_product_tax_profiles_v520 language sql stable security definer set search_path=public,private,pg_temp as $$ select p.* from public.gst_product_tax_profiles_v520 p where p.tenant_id=p_tenant_id and p.variant_id=p_variant_id and p.active and p.effective_from<=coalesce(p_date,current_date) and (p.effective_to is null or p.effective_to>=coalesce(p_date,current_date)) order by p.effective_from desc,p.created_at desc limit 1; $$;
revoke all on function private.gst_profile_for_variant_v520(uuid,uuid,date) from public,anon,authenticated;

create or replace function public.gst_registrations_list_v520(p_tenant_id uuid) returns setof jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return query select jsonb_build_object('id',r.id,'gstin',r.gstin,'pan',r.pan,'legal_name',r.legal_name,'trade_name',r.trade_name,'registration_type',r.registration_type,'state_code',r.state_code,'state_name',s.name,'address_line1',r.address_line1,'address_line2',r.address_line2,'city',r.city,'postal_code',r.postal_code,'country',r.country,'einvoice_enabled',r.einvoice_enabled,'ewaybill_enabled',r.ewaybill_enabled,'returns_enabled',r.returns_enabled,'provider_key',r.provider_key,'validation_status',r.validation_status,'active',r.active,'effective_from',r.effective_from,'effective_to',r.effective_to,'locations',coalesce((select jsonb_agg(jsonb_build_object('location_id',m.location_id,'location_name',l.name,'effective_from',m.effective_from,'effective_to',m.effective_to) order by l.name) from public.gst_location_registrations_v520 m join public.business_locations l on l.id=m.location_id where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.effective_to is null),'[]'::jsonb)) from public.gst_registrations_v520 r join public.gst_state_master_v520 s on s.code=r.state_code where r.tenant_id=p_tenant_id order by r.active desc,r.state_code,r.legal_name;end $$;
revoke all on function public.gst_registrations_list_v520(uuid) from public,anon;grant execute on function public.gst_registrations_list_v520(uuid) to authenticated;

create or replace function public.gst_registration_save_v520(p_tenant_id uuid,p_id uuid,p_gstin text,p_legal_name text,p_trade_name text,p_registration_type text,p_state_code text,p_address_line1 text,p_address_line2 text,p_city text,p_postal_code text,p_einvoice_enabled boolean,p_ewaybill_enabled boolean,p_returns_enabled boolean,p_provider_key text,p_active boolean,p_effective_from date) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid());v_gstin text:=upper(regexp_replace(coalesce(p_gstin,''),'\s','','g'));v_valid jsonb;v_before jsonb;v_type text:=lower(trim(coalesce(p_registration_type,'regular')));v_state text:=trim(coalesce(p_state_code,''));begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.configure') then raise exception 'GST configuration permission required';end if;if nullif(trim(coalesce(p_legal_name,'')),'') is null then raise exception 'GST legal name is required';end if;if v_type not in('regular','composition','casual','sez','isd','tcs','tds','non_resident','other') then raise exception 'Invalid GST registration type';end if;v_valid:=public.gst_gstin_validate_v520(v_gstin);if not coalesce((v_valid->>'structurally_valid')::boolean,false) then raise exception 'GSTIN failed structural/checksum validation';end if;if v_state='' then v_state:=v_valid->>'state_code';end if;if v_state is distinct from (v_valid->>'state_code') then raise exception 'GSTIN state code does not match selected state';end if;if not exists(select 1 from public.gst_state_master_v520 where code=v_state and active and not is_special_code) then raise exception 'Invalid active GST state code';end if;if p_id is not null then select to_jsonb(r) into v_before from public.gst_registrations_v520 r where r.id=p_id and r.tenant_id=p_tenant_id for update;if v_before is null then raise exception 'GST registration not found';end if;end if;insert into public.gst_registrations_v520(id,tenant_id,gstin,pan,legal_name,trade_name,registration_type,state_code,address_line1,address_line2,city,postal_code,einvoice_enabled,ewaybill_enabled,returns_enabled,provider_key,validation_status,active,effective_from,created_by,updated_by) values(v_id,p_tenant_id,v_gstin,v_valid->>'pan',trim(p_legal_name),nullif(trim(coalesce(p_trade_name,'')),''),v_type,v_state,nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(p_einvoice_enabled,false),coalesce(p_ewaybill_enabled,false),coalesce(p_returns_enabled,true),nullif(trim(coalesce(p_provider_key,'')),''),'local_validated',coalesce(p_active,true),coalesce(p_effective_from,current_date),auth.uid(),auth.uid()) on conflict(id) do update set gstin=excluded.gstin,pan=excluded.pan,legal_name=excluded.legal_name,trade_name=excluded.trade_name,registration_type=excluded.registration_type,state_code=excluded.state_code,address_line1=excluded.address_line1,address_line2=excluded.address_line2,city=excluded.city,postal_code=excluded.postal_code,einvoice_enabled=excluded.einvoice_enabled,ewaybill_enabled=excluded.ewaybill_enabled,returns_enabled=excluded.returns_enabled,provider_key=excluded.provider_key,validation_status='local_validated',active=excluded.active,effective_from=excluded.effective_from,updated_by=auth.uid(),updated_at=now();perform private.business_audit_write_v471(p_tenant_id,'gst.registration.save','gst_registration',v_id,v_gstin,v_before,(select to_jsonb(r) from public.gst_registrations_v520 r where r.id=v_id));return v_id;end $$;
