create or replace function public.gst_location_registration_set_v520(p_tenant_id uuid,p_location_id uuid,p_registration_id uuid,p_effective_from date default current_date) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_loc public.business_locations%rowtype;v_reg public.gst_registrations_v520%rowtype;v_state text;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.configure') then raise exception 'GST configuration permission required';end if;select * into v_loc from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active;if not found then raise exception 'Active location not found';end if;select * into v_reg from public.gst_registrations_v520 where id=p_registration_id and tenant_id=p_tenant_id and active;if not found then raise exception 'Active GST registration not found';end if;v_state:=public.gst_state_code_resolve_v520(v_loc.state);if v_state is not null and v_state is distinct from v_reg.state_code then raise exception 'Location state does not match GST registration state';end if;update public.gst_location_registrations_v520 set effective_to=coalesce(p_effective_from,current_date)-1 where tenant_id=p_tenant_id and location_id=p_location_id and effective_to is null and registration_id<>p_registration_id;insert into public.gst_location_registrations_v520(tenant_id,location_id,registration_id,effective_from,created_by) values(p_tenant_id,p_location_id,p_registration_id,coalesce(p_effective_from,current_date),auth.uid()) on conflict(tenant_id,location_id) where effective_to is null do update set registration_id=excluded.registration_id,effective_from=excluded.effective_from;perform private.business_audit_write_v471(p_tenant_id,'gst.location_registration.set','business_location',p_location_id,v_loc.name,null::jsonb,jsonb_build_object('registration_id',p_registration_id,'gstin',v_reg.gstin));end $$;
