create or replace function public.gst_party_profile_save_v520(p_tenant_id uuid,p_id uuid,p_party_type text,p_party_id uuid,p_registration_type text,p_gstin text,p_legal_name text,p_trade_name text,p_state_code text,p_place_of_supply_code text,p_address_line1 text,p_address_line2 text,p_city text,p_postal_code text,p_country text,p_active boolean) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid());v_type text:=lower(trim(coalesce(p_party_type,'')));v_regtype text:=lower(trim(coalesce(p_registration_type,'unregistered')));v_gstin text:=nullif(upper(regexp_replace(coalesce(p_gstin,''),'\s','','g')),'');v_valid jsonb;v_state text:=nullif(trim(coalesce(p_state_code,'')),'');v_before jsonb;v_status text;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.manage') then raise exception 'GST manage permission required';end if;if v_type not in('customer','supplier') then raise exception 'Party type must be customer or supplier';end if;if v_regtype not in('registered','unregistered','composition','sez','export','exempt') then raise exception 'Invalid GST party registration type';end if;if v_type='customer' and not exists(select 1 from public.customers where id=p_party_id and tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;if v_type='supplier' and not exists(select 1 from public.suppliers where id=p_party_id and tenant_id=p_tenant_id) then raise exception 'Supplier not found';end if;if v_regtype in('registered','composition','sez') then if v_gstin is null then raise exception 'GSTIN is required for this registration type';end if;v_valid:=public.gst_gstin_validate_v520(v_gstin);if not coalesce((v_valid->>'structurally_valid')::boolean,false) then raise exception 'GSTIN failed structural/checksum validation';end if;if v_state is null then v_state:=v_valid->>'state_code';end if;if v_state is distinct from (v_valid->>'state_code') then raise exception 'Party GSTIN state and selected state differ';end if;v_status:='local_validated';else v_gstin:=null;v_status:='not_applicable';end if;if p_id is not null then select to_jsonb(g) into v_before from public.gst_party_registrations_v520 g where g.id=p_id and g.tenant_id=p_tenant_id for update;if v_before is null then raise exception 'GST party profile not found';end if;end if;update public.gst_party_registrations_v520 set is_default=false,updated_at=now(),updated_by=auth.uid() where tenant_id=p_tenant_id and party_type=v_type and party_id=p_party_id and active and is_default and effective_to is null and id<>v_id;insert into public.gst_party_registrations_v520(id,tenant_id,party_type,party_id,registration_type,gstin,pan,legal_name,trade_name,state_code,place_of_supply_code,address_line1,address_line2,city,postal_code,country,is_default,validation_status,active,created_by,updated_by) values(v_id,p_tenant_id,v_type,p_party_id,v_regtype,v_gstin,case when v_gstin is null then null else substring(v_gstin,3,10) end,nullif(trim(coalesce(p_legal_name,'')),''),nullif(trim(coalesce(p_trade_name,'')),''),v_state,nullif(trim(coalesce(p_place_of_supply_code,'')),''),nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(nullif(trim(coalesce(p_country,'')),''),'India'),true,v_status,coalesce(p_active,true),auth.uid(),auth.uid()) on conflict(id) do update set registration_type=excluded.registration_type,gstin=excluded.gstin,pan=excluded.pan,legal_name=excluded.legal_name,trade_name=excluded.trade_name,state_code=excluded.state_code,place_of_supply_code=excluded.place_of_supply_code,address_line1=excluded.address_line1,address_line2=excluded.address_line2,city=excluded.city,postal_code=excluded.postal_code,country=excluded.country,is_default=true,validation_status=excluded.validation_status,active=excluded.active,updated_by=auth.uid(),updated_at=now();perform private.business_audit_write_v471(p_tenant_id,'gst.party_profile.save','gst_party_registration',v_id,coalesce(v_gstin,p_party_id::text),v_before,(select to_jsonb(g) from public.gst_party_registrations_v520 g where g.id=v_id));return v_id;end $$;
