create or replace function public.gst_product_profiles_list_v520(p_tenant_id uuid,p_query text default '',p_status text default null,p_limit integer default 500) returns setof jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return query select jsonb_build_object('id',g.id,'variant_id',g.variant_id,'product_id',p.id,'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,'item_type',p.item_type,'supply_kind',g.supply_kind,'hsn_sac',g.hsn_sac,'taxability',g.taxability,'gst_rate',g.gst_rate,'cess_rate',g.cess_rate,'cess_per_unit',g.cess_per_unit,'tax_inclusive',g.tax_inclusive,'reverse_charge',g.reverse_charge,'validation_status',g.validation_status,'source',g.source,'notes',g.notes,'active',g.active,'effective_from',g.effective_from,'effective_to',g.effective_to) from public.gst_product_tax_profiles_v520 g join public.product_variants pv on pv.id=g.variant_id and pv.tenant_id=g.tenant_id join public.products p on p.id=pv.product_id where g.tenant_id=p_tenant_id and (p_status is null or g.validation_status=p_status) and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(g.hsn_sac,'')) like q) order by g.active desc,p.name,pv.name limit greatest(1,least(coalesce(p_limit,500),2000));end $$;
