create or replace function public.gst_setup_health_v520(p_tenant_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare regs int;locs int;mapped int;products int;profiles int;review int;missing_hsn int;party_profiles int;legacy_invalid int;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;select count(*) into regs from public.gst_registrations_v520 where tenant_id=p_tenant_id and active;select count(*) into locs from public.business_locations where tenant_id=p_tenant_id and active;select count(distinct location_id) into mapped from public.gst_location_registrations_v520 where tenant_id=p_tenant_id and effective_to is null;select count(*) into products from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.tenant_id=p_tenant_id and pv.status='active' and p.status='active';select count(*),count(*) filter(where validation_status='review_required'),count(*) filter(where hsn_sac is null) into profiles,review,missing_hsn from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null;select count(*) into party_profiles from public.gst_party_registrations_v520 where tenant_id=p_tenant_id and active and effective_to is null;select count(*) into legacy_invalid from public.products p where p.tenant_id=p_tenant_id and p.status='active' and not exists(select 1 from public.gst_tax_rate_master_v520 r where r.active and r.rate=p.tax_rate);return jsonb_build_object('stage','v5.2-A foundation','registrations',regs,'active_locations',locs,'mapped_locations',mapped,'unmapped_locations',greatest(locs-mapped,0),'active_variants',products,'tax_profiles',profiles,'profiles_review_required',review,'profiles_missing_hsn_sac',missing_hsn,'party_gst_profiles',party_profiles,'legacy_products_with_unlisted_rate',legacy_invalid,'setup_ready