create or replace function public.gst_dashboard_v520(p_tenant_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return jsonb_build_object('setup',public.gst_setup_health_v520(p_tenant_id),'exceptions',jsonb_build_object('irn_pending',0,'irn_failed',0,'ewaybill_missing',0,'gstin_errors',(select count(*) from public.gst_registrations_v520 where tenant_id=p_tenant_id and validation_status='invalid'),'product_profiles_review',(select count(*) from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null and validation_status='review_required'),'missing_hsn_sac',(select count(*) from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null and hsn_sac is null),'itc_mismatch',0),'stage','foundation','provider_status','not_configured');end $$;
