create or replace function public.gst_masters_v520(p_tenant_id uuid,p_date date default current_date) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return jsonb_build_object('states',(select coalesce(jsonb_agg(jsonb_build_object('code',s.code,'name',s.name,'is_union_territory',s.is_union_territory,'is_special_code',s.is_special_code,'active',s.active) order by s.code),'[]'::jsonb) from public.gst_state_master_v520 s where s.active),'rates',(select coalesce(jsonb_agg(jsonb_build_object('rate',r.rate,'label',r.label,'effective_from',r.effective_from,'source_note',r.source_note) order by r.rate),'[]'::jsonb) from public.gst_tax_rate_master_v520 r where r.active and r.effective_from<=coalesce(p_date,current_date) and (r.effective_to is null or r.effective_to>=coalesce(p_date,current_date))),'rules',(select coalesce(jsonb_agg(jsonb_build_object('key',r.rule_key,'effective_from',r.effective_from,'value',r.rule_value,'source_note',r.source_note) order by r.rule_key,r.effective_from),'[]'::jsonb) from public.gst_policy_rules_v520 r where r.active and r.effective_from<=coalesce(p_date,current_date) and (r.effective_to is null or r.effective_to>=coalesce(p_date,current_date))));end $$;
