create or replace function public.pos_offline_product_cache_v486(p_tenant_id uuid,p_device_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_location uuid;v jsonb;begin v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,null);select coalesce(jsonb_agg(x||jsonb_build_object('stock_quantity',case when x->>'item_type'='stock' then greatest(coalesce(lb.quantity,0)-coalesce(lb.reserved_quantity,0)-coalesce(lb.damaged_quantity,0)-coalesce(lb.quarantine_quantity,0),0) else coalesce(nullif(x->>'stock_quantity','')::numeric,0) end,'offline_available_quantity',case when x->>'item_type'='stock' then greatest(coalesce(lb.quantity,0)-coalesce(lb.reserved_quantity,0)-coalesce(lb.damaged_quantity,0)-coalesce(lb.quarantine_quantity,0),0) else coalesce(nullif(x->>'stock_quantity','')::numeric,0) end,'gst_profile',jsonb_strip_nulls(jsonb_build_object('profile_id',gp.id,'supply_kind',gp.supply_kind,'hsn_sac',gp.hsn_sac,'taxability',gp.taxability,'gst_rate',coalesce(gp.gst_rate,prod.tax_rate,0),'cess_rate',coalesce(gp.cess_rate,0),'cess_per_unit',coalesce(gp.cess_per_unit,0),'tax_inclusive',coalesce(gp.tax_inclusive,false),'reverse_charge',coalesce(gp.reverse_charge,false),'validation_status',coalesce(gp.validation_status,'legacy_fallback'),'effective_from',gp.effective_from))) order by x->>'product_name',x->>'sku'),'[]'::jsonb) into v from public.inventory_list_products_v483(p_tenant_id,v_location) as t(x) left join public.location_stock_balances lb on lb.tenant_id=p_tenant_id and lb.location_id=v_location and lb.variant_id=nullif(x->>'variant_id','')::uuid left join public.location_product_settings lps on lps.tenant_id=p_tenant_id and lps.location_id=v_location and lps.variant_id=nullif(x->>'variant_id','')::uuid left join public.product_variants pv on pv.id=nullif(x->>'variant_id','')::uuid and pv.tenant_id=p_tenant_id left join public.products prod on prod.id=pv.product_id and prod.tenant_id=pv.t