create or replace function public.pos_offline_sale_sync_v486(p_tenant_id uuid,p_device_id uuid,p_location_id uuid,p_request_id text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_location uuid;v_existing jsonb;v_result jsonb;v_items jsonb;v_priced jsonb;v_client jsonb;v_server jsonb;v_i integer;v_client_price numeric;v_server_price numeric;v_client_tax numeric;v_server_tax numeric;v_variant uuid;v_customer uuid;v_sale_date date;v_due_date date;v_local text;v_message text;v_code text;v_profile public.gst_product_tax_profiles_v520%rowtype;v_product_tax numeric;begin if nullif(trim(coalesce(p_request_id,'')),'') is null then raise exception 'Request ID is required';end if;v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,p_location_id);perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':offline:'||trim(p_request_id),0));select server_response into v_existing from public.pos_offline_sync_v486 where tenant_id=p_tenant_id and request_id=trim(p_request_id) and status='synced';if v_existing is not null then return v_existing||jsonb_build_object('idempotent_replay',true);end if;v_items:=coalesce(p_payload->'items','[]'::jsonb);if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then raise exception 'Offline invoice has no items';end if;v_customer:=nullif(p_payload->>'customer_id','')::uuid;v_local:=nullif(trim(coalesce(p_payload->>'local_invoice_number','')),'');if v_customer is null or not exists(select 1 from public.customers c where c.id=v_customer and c.tenant_id=p_tenant_id and c.status='active') then return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'CUSTOMER_UNAVAILABLE','Customer is no longer available.',p_payload);end if;v_sale_date:=coalesce(nullif(p_payload->>'sale_date','')::date,current_date);v_due_date:=nullif(p_payload->>'due_date','')::date;v_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);for v_i in 0..jsonb_array_length(v_items)-1 loop v_client:=v_items->v_i;v_server:=v_priced->v_i;v_variant:=nullif(v_client->>'variant_id','')::uuid;v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);if abs(v_client_price-v_server_price)>0.005 then v_message:=format('Price changed for product %s. Offline %s, current %s.',v_variant,round(v_client_price,2),round(v_server_price,2));return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'PRICE_CHANGED',v_message,p_payload);end if;select p.tax_rate into v_product_tax from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;if not found then return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'PRODUCT_UNAVAILABLE','A product on the offline invoice is no longer available.',p_payload);end if;select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);v_server_tax:=case when v_profile.id is null then coalesce(v_product_tax,0) when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0) else 0 end;v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);if abs(v_client_tax-v_server_tax)>0.0001 then v_message:=format('Tax changed for product %s. Offline %s, current %s.',v_variant,round(v_client_tax,4),round(v_server_tax,4));return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'TAX_CHANGED',v_message,p_payload);end if;end loop;insert into public.pos_offline_sync_v486(tenant_id,request_id,device_id,location_id,local_invoice_number,status,payload_snapshot,attempts,last_attempt_at,created_by,updated_at) values(p_tenant_id,trim(p_request_id),p_device_id,v_location,v_local,'syncing',p_payload,1,now(),auth.uid(),now()) on conflict(tenant_id,request_id) do update set status='syncing',payload_snapshot=excluded.payload_snapshot,attempts=public.pos_offline_sync_v486.attempts+1,last_attempt_at=now(),updated_at=now(),conflict_code=null,conflict_message=null;begin v_result:=public.sales_create_v489(p_tenant_id,v_customer,v_sale_date,v_due_date,v_items,coalesce(nullif(p_payload->>'additional_charges','')::numeric,0),coalesce(nullif(p_payload->>'round_off','')::numeric,0),coalesce(nullif(p_payload->>'initial_payment','')::numeric,0),coalesce(nullif(p_payload->>'payment_method',''),'cash'),coalesce(p_payload->>'payment_reference',''),trim(concat_ws(' • ',nullif(p_payload->>'notes',''),'Offline POS '||coalesce(v_local,''))),v_location,p_device_id,trim(p_request_id));exception when others then v_message:=sqlerrm;if v_message ilike '%stock%' or v_message ilike '%serial%' or v_message ilike '%batch%' or v_message ilike '%reconciled%' then v_code:='STOCK_CONFLICT';else v_code:='SERVER_VALIDATION';end if;return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,v_code,v_message,p_payload);end;v_result:=coalesce(v_result,'{}'::jsonb)||jsonb_build_object('ok',true,'status','synced','request_id',trim(p_request_id),'local_invoice_number',v_local,'offline_sync','v5.2-foundation','gst_engine','gst_v520');update public.pos_offline_sync_v486 set status='synced',server_response=v_result,conflict_code=null,conflict_message=null,synced_at=now(),last_attempt_at=now(),updated_at=now() where tenant_id=p_tenant_id and request_id=trim(p_request_id);return v_result;end $$;
revoke all on function public.pos_offline_sale_sync_v486(uuid,uuid,uuid,text,jsonb) from public,anon;grant execute on function public.pos_offline_sale_sync_v486(uuid,uuid,uuid,text,jsonb) to authenticated;

insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(214,'5.2.0-foundation','GST & Compliance Foundation','Normalized GST masters/registrations/party/product profiles, centralized GST quote engine, compliance permissions/navigation, setup diagnostics and offline POS tax/cache hardening. No GSP/IRP production integration yet.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;
create or replace function public.thq_v520_foundation_verify() returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare miss text[]:='{}';r record;begin for r in select * from (values ('gst_state_master_v520','public.gst_state_master_v520'),('gst_tax_rate_master_v520','public.gst_tax_rate_master_v520'),('gst_policy_rules_v520','public.gst_policy_rules_v520'),('gst_registrations_v520','public.gst_registrations_v520'),('gst_location_registrations_v520','public.gst_location_registrations_v520'),('gst_party_registrations_v520','public.gst_party_registrations_v520'),('gst_product_tax_profiles_v520','public.gst_product_tax_profiles_v520')) v(name,reg) loop if to_regclass(r.reg) is null then miss:=array_append(miss,r.name);end if;end loop;for r in select * from (values ('gst_gstin_validate_v520','public.gst_gstin_validate_v520(text)'),('gst_registrations_list_v520','public.gst_registrations_list_v520(uuid)'),('gst_registration_save_v520','public.gst_registration_save_v520(uuid,uuid,text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,text,boolean,date)'),('gst_location_registration_set_v520','public.gst_location_registration_set_v520(uuid,uuid,uuid,date)'),('gst_party_profiles_list_v520','public.gst_party_profiles_list_v520(uuid,text,text,integer)'),('gst_party_profile_save_v520','public.gst_party_profile_save_v520(uuid,uuid,text,uuid,text,text,text,text,text,text,text,text,text,text,text,boolean)'),('gst_product_profiles_list_v520','public.gst_product_profiles_list_v520(uuid,text,text,integer)'),('gst_product_profile_save_v520','public.gst_product_profile_save_v520(uuid,uuid,text,text,text,numeric,numeric,numeric,boolean,boolean,text,date)'),('gst_quote_v520','public.gst_quote_v520(uuid,uuid,text,uuid,date,text,text,jsonb,numeric,numeric)'),('gst_setup_health_v520','public.gst_setup_health_v520(uuid)'),('gst_dashboard_v520','public.gst_dashboard_v520(uuid)'),('gst_masters_v520','public.gst_masters_v520(uuid,date)')) v(name,sig) loop if to_regprocedure(r.sig) is null then miss:=array_append(miss,r.name);end if;end loop;if not exists(select 1 from public.modules where key='gst_compliance' and is_active) then miss:=array_append(miss,'module.gst_compliance');end if;if not exists(select 1 from public.permissions where key='gst_compliance.view') then miss:=array_append(miss,'permission.gst_compliance.view');end if;if not exists(select 1 from public.gst_tax_rate_master_v520 where rate=40 and effective_from='2025-09-21') then miss:=array_append(miss,'rate.40');end if;if position('product_variants pv join public.products p' in lower(pg_get_functiondef('public.pos_offline_sale_sync_v486(uuid,uuid,uuid,text,jsonb)'::regprocedure)))=0 then miss:=array_append(miss,'offline.tax_lookup_fix');end if;if not exists(select 1 from public.thq_schema_releases where migration_no=214 and schema_version='5.2.0-foundation') then miss:=array_append(miss,'migration.214');end if;return jsonb_build_object('ready',cardinality(miss)=0,'missing',to_jsonb(miss),'schema_version','5.2.0-foundation','migration_no',214,'stage','GST Foundation','provider_connected',false,'production_irp_enabled',false,'principle','ONE Invoice / ONE GST Calculation / ONE Accounting Entry Source / ONE GST Status / ONE Audit Trail');end $$;
revoke all on function public.thq_v520_foundation_verify() from public,anon;grant execute on function public.thq_v520_foundation_verify() to authenticated;
commit;